package timex_test

import (
	"testing"
	"time"

	"github.com/egdaemon/eg/internal/timex"
	"github.com/stretchr/testify/require"
)

// DO NOT EDIT: This file was auto generated by egautotest.

func TestAdjustableClockNow(t *testing.T) {
	t.Run("returns the initial time", func(t *testing.T) {
		ts := time.Date(2024, 1, 15, 12, 30, 45, 0, time.UTC)
		c := timex.NewAdjustableClock(ts)
		require.Equal(t, ts, c.Now())
	})

	t.Run("returns the time after Set", func(t *testing.T) {
		c := timex.NewAdjustableClock(time.Time{})
		ts := time.Date(2025, 6, 1, 0, 0, 0, 0, time.UTC)
		c.Set(ts)
		require.Equal(t, ts, c.Now())
	})

	t.Run("returns the time after Advance", func(t *testing.T) {
		initial := time.Date(2024, 3, 10, 8, 0, 0, 0, time.UTC)
		c := timex.NewAdjustableClock(initial)
		c.Advance(2 * time.Hour)
		require.Equal(t, initial.Add(2*time.Hour), c.Now())
	})

	t.Run("returns the time after multiple Advances", func(t *testing.T) {
		initial := time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)
		c := timex.NewAdjustableClock(initial)
		c.Advance(time.Second)
		c.Advance(3 * time.Minute)
		c.Advance(-500 * time.Millisecond)
		require.Equal(t, initial.Add(time.Second+3*time.Minute-500*time.Millisecond), c.Now())
	})

	t.Run("returns zero time when constructed with zero", func(t *testing.T) {
		c := timex.NewAdjustableClock(time.Time{})
		require.True(t, c.Now().IsZero())
	})

	t.Run("returns the time after Set then Advance", func(t *testing.T) {
		c := timex.NewAdjustableClock(time.Time{})
		ts := time.Date(2025, 12, 25, 23, 59, 59, 0, time.UTC)
		c.Set(ts)
		c.Advance(1 * time.Second)
		require.Equal(t, ts.Add(1*time.Second), c.Now())
	})
}
